public class PlayerEvents {
	public static final EventGroup GROUP = new EventGroup("player");

	public static final SimpleEvent<Player> LOGGED_IN = GROUP.makeEvent("logged_in");
	public static final SimpleEvent<Player> LOGGED_OUT = GROUP.makeEvent("logged_out");
	public static final SimpleEvent<Player> RESPAWN = GROUP.makeEvent("respawn");
	public static final SimpleEvent<Player> TICK = GROUP.makeEvent("tick");
	public static final SimpleEvent<Player> CHANGE_DIMENSION = GROUP.makeEvent("change_dimension");
	public static final SimpleEvent<Player> COPY_FROM = GROUP.makeEvent("copy_from");
	public static final SimpleEvent<Player> DEATH = GROUP.makeEvent("death");
	public static final SimpleEvent<Player> ATTACK = GROUP.makeEvent("attack");
	public static final SimpleEvent<Player> USE_ITEM = GROUP.makeEvent("use_item");

	public static void init() {
		LOGGED_IN.addHandler(e -> e.player.tell(Component.literal("Welcome to the server!")));
		LOGGED_OUT.addHandler(e -> ConsoleJS.SERVER.info(e.player.getName().getString() + " left the server"));
	}
}
